_file_map = {

    "align_qa_pair.baml": "// Dataset cleaning utilities for aligning questions and answers\n\nfunction QuestionAnswerAlignment(\n  question: string,\n  answer: string\n) -> AlignedQAPair {\n  client GLM_4_6\n\n  prompt #\"\n    You are a dataset quality specialist focused on ensuring alignment between questions and answers in a BIM (Building Information Modeling) question-answering dataset.\n\n    TASK: Analyze the question-answer pair and ensure they are properly aligned in structure, scope, and granularity.\n\n    ORIGINAL QUESTION:\n    {{ question }}\n\n    ORIGINAL ANSWER:\n    {{ answer }}\n\n    ---\n\n    ALIGNMENT PRINCIPLES:\n\n    1. **Structural Alignment**: The question should clearly indicate the expected answer structure\n       - If answer is a list, question should ask for \"a list of...\"\n       - If answer is a count, question should ask \"how many...\"\n       - If answer is a breakdown by category, question should request that breakdown\n\n    2. **Scope Alignment**: The question scope should match what the answer provides\n       - If answer covers specific types/categories, question should ask for those types/categories\n       - Avoid ambiguous phrasings that could be interpreted differently than the answer provides\n\n    3. **Granularity Alignment**: The level of detail should match\n       - If answer provides \"X per Y\", question should ask for quantities \"of each Y\" or \"by Y\"\n       - If answer is aggregate, question should ask for total/overall information\n\n    4. **Clarity**: Both question and answer should be clear and professional\n       - Questions can be rephrased for clarity while preserving intent\n       - Answers can be formatted better (e.g., adding labels, structure) without changing facts\n\n    CRITICAL CONSTRAINTS:\n    - DO NOT modify, add, or remove any factual information from the answer\n    - DO NOT change numerical values, element types, or technical details\n    - DO NOT invent information not present in the original answer\n    - If the pair is already well-aligned, return them unchanged (set was_modified to false)\n\n    EXAMPLES OF GOOD ALIGNMENTS:\n\n    Example 1 - List Structure:\n    Original Q: \"What types of pipes are used in the building, including their quantities?\"\n    Original A: \"Total Pipe Segments: 60\\nPipe Types:\\n- hwa afvoer: 60 segments\"\n\n    Aligned Q: \"Could you provide me with a list of the types of pipes used in the building and the quantities of each type?\"\n    Aligned A: \"Total Pipe Segments: 60\\nPipe Types:\\n- hwa afvoer: 60 segments\"\n    Reason: Question now explicitly asks for \"a list\" and \"quantities of each type\", matching the answer structure\n\n    Example 2 - Already Aligned:\n    Original Q: \"How many windows are on the ground floor?\"\n    Original A: \"There are 12 windows on the ground floor.\"\n\n    Aligned Q: \"How many windows are on the ground floor?\"\n    Aligned A: \"There are 12 windows on the ground floor.\"\n    Reason: Already perfectly aligned, no changes needed\n\n    Example 3 - Formatting Improvement:\n    Original Q: \"What are the room areas?\"\n    Original A: \"Room A: 25.5 Room B: 30.2 Room C: 18.7\"\n\n    Aligned Q: \"What are the areas of each room in the building?\"\n    Aligned A: \"Room areas:\\n- Room A: 25.5 m²\\n- Room B: 30.2 m²\\n- Room C: 18.7 m²\"\n    Reason: Question clarified, answer formatted for readability, no facts changed\n\n    Now analyze the provided question-answer pair and produce an aligned version.\n\n    {{ ctx.output_format }}\n  \"#\n}\n\n// Test with the pipes example\ntest stairs_alignment_test {\n  functions [QuestionAnswerAlignment]\n  args {\n    question \"What stair types are used, with their quantities?\"\n    answer #\"\n        Total Stairs: 71\n\n   Stair Types:\n   - 24_DD_ betontrap: 32 stairs (45.1%)\n   - 24_stair_DD_trapbordes: 18 stairs (25.4%)\n   - 24-DD-stalentrap verd: 14 stairs (19.7%)\n   - Trap_DD-trap woning type F: 2 stairs (2.8%)\n   - Trap_DD-trap woning type G: 2 stairs (2.8%)\n   - 24-DD-stalen trap beganegrond: 1 stairs (1.4%)\n   - 28_stair_DD_trapbordes: 1 stairs (1.4%)\n   - DD-KOOILADDER: 1 stairs (1.4%)\n\n   Concrete Stairs:\n   - 24_DD_ betontrap: 32 stairs\n\n   Steel Stairs:\n   - 24-DD-stalen trap beganegrond: 1 stairs\n   - 24-DD-stalentrap verd: 14 stairs\n\n   Stair Landings:\n   - 24_stair_DD_trapbordes: 18 landings\n   - 28_stair_DD_trapbordes: 1 landings\n    \"#\n  }\n}\n\n// Test with already aligned pair\ntest already_aligned_test {\n  functions [QuestionAnswerAlignment]\n  args {\n    question \"How many walls are in the building?\"\n    answer \"There are 156 walls in the building.\"\n  }\n}\n",
    "answer_verifier.baml": "// BAML template for BIM Information Extraction Evaluation\n// Evaluates system responses using 3-category classification: Correct / Wrong / Abstained\n\nenum QuestionCategory {\n  Category1 @alias(\"1\")\n  Category2 @alias(\"2\")\n  Category3 @alias(\"3\")\n  Category4 @alias(\"4\")\n}\n\n\n\nfunction EvaluateResponse(\n  question: string,\n  category: QuestionCategory,\n  ground_truth: string,\n  system_response: string,\n  bim_context: string? @description(\"Brief description of what data is available in the BIM model\")\n) -> AnswerEvaluationResult {\n  client GLM_4_6\n\n  prompt #\"\n    You are evaluating a BIM information extraction system's response to a question.\n\n    QUESTION CATEGORY: {{ category }}\n    QUESTION: {{ question }}\n\n    BIM CONTEXT: {{ bim_context }}\n\n    GROUND TRUTH: {{ ground_truth }}\n\n    SYSTEM RESPONSE: {{ system_response }}\n\n    ---\n\n    EVALUATION TASK:\n\n    Classify the system response as one of:\n    - \"correct\": System provided accurate answer\n    - \"wrong\": System provided inaccurate/hallucinated answer\n    - \"abstained\": System explicitly declined to answer\n\n    EVALUATION CRITERIA BY CATEGORY:\n\n    Categories 1, 2, 3 (Direct Retrieval, Computational, Geometric):\n    - CORRECT: The system response contains all essential information from the ground truth AND does not contradict it.\n      * Additional contextual information beyond the ground truth is acceptable and often beneficial\n      * The core facts/values from ground truth must be present (allowing for reasonable rounding)\n      * Extra details should be factually accurate, but their presence doesn't disqualify the answer\n\n    - WRONG:\n      * Missing essential information from ground truth\n      * Contradicts ground truth facts\n      * Contains factual errors or hallucinations\n\n    - ABSTAINED: System explicitly declines (e.g., \"I cannot determine...\", \"Insufficient information...\").\n\n    Category 4 (Incomplete Information):\n    - CORRECT: Answer includes ALL of:\n      1. Acknowledgment that some information is missing from BIM model\n      2. Explicit statement of reasonable assumptions made\n      3. Useful estimate or partial answer\n      4. There are no factual errors in the information extracted from the BIM model\n\n    - WRONG:\n      - Missing assumptions (presents estimate as fact)\n      - Unreasonable assumptions\n      - Hallucination of data not in model\n\n    - ABSTAINED: System declined to answer (also acceptable for Category 4)\n\n    ABSTENTION DETECTION:\n    Look for explicit phrases indicating refusal:\n    - \"I cannot determine...\"\n    - \"Insufficient information...\"\n    - \"This data is not available...\"\n    - \"I am unable to answer...\"\n    - \"Cannot be calculated without...\"\n\n    Do NOT count as abstention:\n    - Expressions of uncertainty while still providing an answer\n    - Conditional statements (\"If X, then Y\")\n    - Partial information followed by explanation\n\n    IMPORTANT GUIDELINES:\n    1. Compare semantic content, not exact wording\n    2. Allow for reasonable rounding/approximation in numerical answers (e.g. 2%)\n    3. For Category 4: Prioritize transparency about limitations over precision\n    4. Be strict about hallucinations - any fabricated data should be marked WRONG\n    5. Focus on whether the response would be useful and non-misleading to a BIM professional\n\n    {{ ctx.output_format }}\n  \"#\n}\n\n// Test function for EvaluateResponse\ntest radiator_count_test {\n  functions [EvaluateResponse]\n  args {\n    question \"How many radiator are there in room A202?\"\n    category Category1\n    ground_truth \"There is one radiator in room A202.\"\n    system_response \"I could find one radiator in room A202.\"\n    bim_context \"this is the bim model for a duplex house.\"\n  }\n}\n\n// Test function for pipe types with additional context\n// This tests whether additional contextual information is properly accepted\ntest pipe_types_with_context_test {\n  functions [EvaluateResponse]\n  args {\n    question \"What types of pipes are used in the building, including their quantities?\"\n    category Category1\n    ground_truth \"Total Pipe Segments: 60 Pipe Types: - hwa afvoer: 60 segments\"\n    system_response #\"\n      Based on my analysis of the IFC model, the building contains the following pipe-related elements:\n\n      ## Main Pipe Types:\n\n      ### 1. HWA Afvoer (Rainwater Drainage Pipes)\n      - **Quantity**: 60 elements\n      - **Type**: IfcBuildingElementProxy\n      - **Material**: Zinc (04 Zink)\n      - **Classification**: Pipe Segment\n      - **Layer**: 5210_afvoeren - regenwater (rainwater drainage)\n      - **Position**: Exterior\n      - **Structural Function**: Non-Load-Bearing Element\n\n      ### 2. Waterslag (Water Splash/Drip Edge)\n      - **Quantity**: 35 elements\n      - **Type**: IfcCovering\n      - **Function**: Water management elements, typically installed at roof edges or transitions\n\n      ## Summary:\n      - **Total pipe-related elements**: 95\n      - **Primary system**: Rainwater drainage (HWA system)\n      - **Material**: All HWA pipes are made of zinc\n      - **Location**: All exterior elements\n      - **Modeling approach**: Pipes are modeled as IfcBuildingElementProxy elements rather than standard IfcPipe entities (due to IFC2X3 schema limitations)\n\n      The building appears to have a comprehensive rainwater drainage system with 60 zinc pipe segments and 35 water splash protection elements, all designed for exterior installation and rainwater management.\n    \"#\n    bim_context null\n  }\n}\n",
    "category_validator.baml": "// Category validation for BIM question-answer pairs\n// Validates that questions are correctly categorized according to the 4-category taxonomy\n\nfunction ValidateQuestionCategory(\n  question: string,\n  answer: string,\n  current_category: string\n) -> CategoryValidationResult {\n  client GLM_4_6\n\n  prompt #\"\n    You are a BIM dataset quality specialist responsible for validating question categorization according to a strict 4-category taxonomy.\n\n    QUESTION: {{ question }}\n\n    ANSWER: {{ answer }}\n\n    CURRENT CATEGORY: {{ current_category }}\n\n    ---\n\n    TAXONOMY DEFINITIONS:\n\n    **Category 1: Direct Information Retrieval**\n    Tasks answerable through direct access to explicitly stored BIM element properties, regardless of the number of elements involved.\n\n    Key characteristics:\n    - Information is directly stored in BIM element properties\n    - No calculations or derivations needed\n    - Can involve single or multiple elements\n    - Simple lookups or listings\n\n    Examples:\n    - \"What is the width of the entrance door?\"\n    - \"List all doors in the building\"\n    - \"What material is used for wall W-101?\"\n    - \"What types of windows are installed?\"\n\n    **Category 2: Computational Aggregation**\n    Tasks requiring mathematical or logical operations (counting, averaging, filtering with conditions) on directly accessible data.\n\n    Key characteristics:\n    - Requires counting, summing, averaging, or filtering\n    - Data is directly accessible, but needs aggregation\n    - Involves logical operations or conditional filtering\n    - No geometric/spatial calculations needed\n\n    Examples:\n    - \"How many windows are there in the building?\"\n    - \"What is the average thickness of all walls?\"\n    - \"How many doors are on the second floor?\"\n    - \"What is the total length of all pipes?\"\n\n    **Category 3: Geometric/Spatial Computation**\n    Tasks requiring derived calculations from geometric or topological relationships not explicitly stored in the model.\n\n    Key characteristics:\n    - Requires geometric calculations (areas, volumes, distances)\n    - Involves spatial relationships or topology\n    - Needs derivation from geometric representations\n    - May require complex spatial analysis\n\n    Examples:\n    - \"What is the Gross Floor Area of the building?\"\n    - \"What is the volume of room A202?\"\n    - \"Which bedroom is closest to the main entrance?\"\n    - \"What is the total surface area of all exterior walls?\"\n\n    **Category 4: Incomplete Information Scenarios**\n    Tasks where complete accurate answers require information not available in the BIM model, potentially addressable through assumptions or external data.\n\n    Key characteristics:\n    - Requires information not typically stored in BIM models\n    - May need external data sources or databases\n    - Requires significant assumptions\n    - Answer depends on data beyond geometric/property information\n\n    Examples:\n    - \"What is the Global Warming Potential of this building?\" (if GWP values not stored)\n    - \"What is the construction cost of the building?\" (if cost data not included)\n    - \"What is the thermal transmittance of wall type A?\" (if U-values not stored)\n    - \"How long will it take to construct this building?\"\n\n    ---\n\n    CLASSIFICATION RULES:\n\n    1. **If in doubt between two categories, choose the MORE DIFFICULT one:**\n       - Between 1 and 2: Choose 2 (aggregation is more complex than retrieval)\n       - Between 2 and 3: Choose 3 (geometric calculation is more complex than aggregation)\n       - Between 3 and 4: Choose 4 (incomplete information is more challenging)\n\n    2. **Distinguishing Category 1 vs 2:**\n       - Category 1: \"What types of pipes?\" (listing) → Direct retrieval\n       - Category 2: \"How many types of pipes?\" (counting) → Aggregation needed\n\n    3. **Distinguishing Category 2 vs 3:**\n       - Category 2: \"How many walls are there?\" (counting elements) → Simple aggregation\n       - Category 3: \"What is the total wall area?\" (geometric calculation) → Spatial computation\n\n    4. **Distinguishing Category 3 vs 4:**\n       - Category 3: \"What is the floor area?\" (geometric, but derivable) → Spatial computation\n       - Category 4: \"What is the embodied carbon?\" (needs external data) → Incomplete information\n\n    5. **Questions asking for lists of values require aggregation:**\n       - \"List all door widths\" → Category 2 (must collect/aggregate from multiple elements)\n       - \"What is the width of door D-101?\" → Category 1 (single direct lookup)\n\n    ---\n\n    VALIDATION TASK:\n\n    1. Analyze the question and answer to determine the correct category\n    2. Compare with the current category\n    3. If they match: set `updated` to false\n    4. If they differ: set `updated` to true and provide the correct category\n    5. Always provide clear reasoning in the `thought` field\n\n    Be strict in your classification. When uncertain between two categories, always choose the more difficult one.\n\n    {{ ctx.output_format }}\n  \"#\n}\n\n// Test: Category 1 - Direct retrieval (correctly classified)\ntest direct_retrieval_correct {\n  functions [ValidateQuestionCategory]\n  args {\n    question \"What is the width of the entrance door?\"\n    answer \"The entrance door has a width of 900mm.\"\n    current_category \"1\"\n  }\n}\n\n// Test: Category 2 - Should be 2, but marked as 1 (misclassified)\ntest aggregation_misclassified {\n  functions [ValidateQuestionCategory]\n  args {\n    question \"How many windows are in the building?\"\n    answer \"There are 45 windows in the building.\"\n    current_category \"1\"\n  }\n}\n\n// Test: Category 3 - Geometric computation (correctly classified)\ntest geometric_correct {\n  functions [ValidateQuestionCategory]\n  args {\n    question \"What is the Gross Floor Area of level 1?\"\n    answer \"The Gross Floor Area of level 1 is 1,250.5 m².\"\n    current_category \"3\"\n  }\n}\n\n// Test: Category 2 - List with aggregation (borderline case)\ntest list_aggregation {\n  functions [ValidateQuestionCategory]\n  args {\n    question \"What types of pipes are used in the building, including their quantities?\"\n    answer \"Total Pipe Segments: 60\\nPipe Types:\\n- hwa afvoer: 60 segments\"\n    current_category \"1\"\n  }\n}\n\n// Test: Category 4 - Incomplete information\ntest incomplete_information {\n  functions [ValidateQuestionCategory]\n  args {\n    question \"What is the Global Warming Potential of this building?\"\n    answer \"The GWP cannot be determined as material carbon factors are not stored in the BIM model.\"\n    current_category \"4\"\n  }\n}\n",
    "clients.baml": "// Learn more about clients at https://docs.boundaryml.com/docs/snippets/clients/overview\n\n// Z.AI GLM 4.6 (with Coding Plan API key)\nclient<llm> GLM_4_6{\n  provider openai\n  retry_policy Exponential\n  options {\n    base_url \"https://api.z.ai/api/coding/paas/v4\"\n    model \"glm-4.6\"\n    api_key env.Z_AI_API_KEY\n    temperature 0.1\n    max_tokens 8192\n  }\n}\n\n// Minimax M2 client\nclient<llm> MinimaxM2 {\n  provider openai\n  retry_policy Exponential\n  options {\n    base_url \"https://api.minimax.chat/v1\"\n    model \"minimax-m2\"\n    api_key env.MINIMAX_API_KEY\n    temperature 0.1\n    max_tokens 8192\n  }\n}\n\n\n// https://docs.boundaryml.com/docs/snippets/clients/retry\nretry_policy Constant {\n  max_retries 3\n  strategy {\n    type constant_delay\n    delay_ms 200\n  }\n}\n\nretry_policy Exponential {\n  max_retries 7\n  strategy {\n    type exponential_backoff\n    delay_ms 200\n    multiplier 2\n    max_delay_ms 40000\n  }\n}\n",
    "cobbie.baml": "// Cobbie Agent - Extract information from BIM models\nfunction Cobbie(\n  user_input: string,\n  available_tools: string,\n  previous_attempts: string? @description(\"Previous execution results, if any\"),\n  model_path: string? @description(\"Path to the IFC model file, if available\")\n) -> CodeAction | FinalAnswer {\n  client GLM_4_6\n  prompt #\"\n    You are a helpful assistant specialising in retrieving information from BIM models using Python code and the IfcOpenShell library. To facilitate this task, you also have access to higher-level functions that will help you with the most common information retrieval tasks (referred to later as the 'helper functions'). These helper functions can be used directly in your Python code as they are already pre-loaded; there is no need to import them.\n\n    When a user asks a question, you can either:\n    1. Write Python code to investigate further (returns CodeAction)\n    2. Provide the final answer if you have sufficient information (returns FinalAnswer)\n\n    {% if model_path %}\n    IMPORTANT: The IFC model path is: {{ model_path }}\n    Use this exact path in your Python code when calling IFC functions.\n    {% endif %}\n\n    Question:\n    {{ user_input }}\n\n    Helper functions:\n    {{ available_tools }}\n\n    {% if previous_attempts %}\n    Previous Results:\n    {{ previous_attempts }}\n    {% endif %}\n\n  ANSWERING GUIDELINES:\n    - Use the provided helper functions rather than calling ifcopenshell directly whenever possible.\n    - When you must use ifcopenshell directly, always query the query_ifcopenshell_docs tool first to verify correct usage. Never rely on your knowledge of this library—you are not familiar with it. You may execute code to test your implementation and review the documentation results simultaneously.\n    - Thoroughly explore the BIM model before answering: check all relevant room names, element types, materials, Psets, and ePsets as needed for the question. Property naming conventions and ontologies vary significantly between models.\n    - Pay careful attention to the specific element types, properties, and scope requested in the question.\n    - Answer exactly what is asked—no more, no less. Keep responses focused and concise.\n\n    Now, choose your next action (only one):\n    - CodeAction: If you need to explore/analyze more with Python code\n    - FinalAnswer: If you have enough information to answer completely\n\n    {{ ctx.output_format }}\n  \"#\n}\n\n// Test function for BIMQAS\ntest test_cobbie {\n  functions [Cobbie]\n  args {\n    user_input \"How many walls are in the building?\"\n    available_tools #\"\n      def count_walls() -> int:\n          '''Count all wall elements in the IFC model'''\n\n      def get_wall_materials(wall_guid: str) -> list:\n          '''Get material information for a specific wall'''\n    \"#\n  }\n}\n",
    "create_helper_function.baml": "// The agent identifies, extracts and implements reusable helper functions from the successful answers generated by Cobbie.\n\n// Union return type: either continue with code action or provide final implementation\nfunction HelperFunctionCreator(\n  history: string @description(\"Complete execution history from Cobbie including thoughts, code, results, and final answer\"),\n  example_question: string @description(\"The question that was successfully answered by Cobbie\"),\n  example_answer: string @description(\"The ground truth answer to the example question\"),\n  example_bim_model: string @description(\"Path to the BIM model used to answer the example question\"),\n  other_bim_models_for_testing: string[] @description(\"List of paths to other available BIM models for testing generalization\"),\n  function_name: string @description(\"Name of the helper function to create\"),\n  function_description: string @description(\"Detailed description of what the helper function should do, including parameters and return type\"),\n  previous_attempts: string? @description(\"Previous code execution results and attempts, if any\")\n) -> CodeAction | NewHelperFunction {\n  client GLM_4_6\n  prompt #\"\n    You are an expert Python programmer specializing in creating reusable helper functions for BIM (Building Information Modeling) analysis using the IfcOpenShell library.\n\n    Your task is to extract and implement a reusable helper function based on a successful Cobbie execution.\n\n    CONTEXT:\n    Cobbie successfully answered the following question:\n    Question: {{ example_question }}\n    Ground Truth Answer: {{ example_answer }}\n\n    Using BIM model: {{ example_bim_model }}\n\n    EXECUTION HISTORY:\n    The following shows how Cobbie solved this problem (including all thoughts, code, and results):\n    {{ history }}\n\n    YOUR TASK:\n    Create a reusable helper function with:\n    - Name: {{ function_name }}\n    - Description: {{ function_description }}\n\n    REQUIREMENTS:\n    1. **Type Safety**: Use proper type hints (typing.List, typing.Dict, etc.) for all parameters and return types\n    2. **Docstring**: Include comprehensive docstring with:\n       - Brief description\n       - Args section with type information\n       - Returns section with type information\n       - Example usage\n    3. **Return Type**: Return structured data (lists, dicts, primitives), NOT formatted strings\n    4. **Error Handling**: Use try-except blocks for robust error handling\n    5. **Generalization**: The function should work across different BIM models, not just the example\n    6. **Testing**: Test the function with multiple BIM models to ensure it's not overfitted\n\n    AVAILABLE FOR TESTING:\n    - Example model: {{ example_bim_model }}\n    - Other models: {{ other_bim_models_for_testing | join(\", \") }}\n\n    IMPORTANT GUIDELINES:\n    - **Always use query_ifcopenshell_docs** before implementing ifcopenshell code to ensure correct usage\n    - Extract the reusable pattern from the execution history, not just copy-paste the code\n    - Make sure the function signature matches what's described in function_description\n    - Test that the function returns the exact type specified in its signature\n    - Test on multiple BIM models to avoid overfitting to naming conventions or data formats\n\n    {% if previous_attempts %}\n    PREVIOUS ATTEMPTS:\n    {{ previous_attempts }}\n\n    Learn from previous attempts and iterate to improve the function.\n    {% endif %}\n\n    You can either:\n    1. **CodeAction**: Write Python code to develop, test, or validate the function\n    2. **NewHelperFunction**: Provide the final function implementation if complete and tested\n\n    Choose your next action based on your progress:\n    - Use CodeAction if you need to: query docs, develop the function, test it, or debug issues\n    - Use NewHelperFunction when you have a complete, tested, working function\n\n    {{ ctx.output_format }}\n  \"#\n}\n\n// Test function for HelperFunctionCreator\ntest HelperFunctionCreatorTest {\n  functions [HelperFunctionCreator]\n  args {\n    history #\"\n      --- Iteration 1 ---\n      Thoughts: I need to find all doors and group them by their floor level.\n\n      Code:\n      model = ifcopenshell.open(path_ifc_model)\n      doors = model.by_type('IfcDoor')\n      print(f\"Found {len(doors)} doors\")\n\n      Result:\n      Found 15 doors\n\n      --- Iteration 2 ---\n      Thoughts: Now I need to get the floor level for each door using spatial containment.\n\n      Code:\n      import ifcopenshell.util.element as util\n      floor_doors = {}\n      for door in doors:\n          containers = util.get_referenced_structures(door)\n          if containers and containers[0].is_a('IfcBuildingStorey'):\n              floor_name = containers[0].Name\n              if floor_name not in floor_doors:\n                  floor_doors[floor_name] = []\n              floor_doors[floor_name].append(door)\n      print(floor_doors.keys())\n\n      Result:\n      dict_keys(['Level 1', 'Level 2', 'Level 3'])\n\n      --- Final Answer ---\n      Thoughts: I've successfully grouped all doors by floor level.\n      Answer: There are 6 doors on Level 1, 5 doors on Level 2, and 4 doors on Level 3.\n    \"#\n    example_question \"How many doors are on each floor?\"\n    example_answer \"Level 1: 6 doors, Level 2: 5 doors, Level 3: 4 doors\"\n    example_bim_model \"/path/to/test/model.ifc\"\n    other_bim_models_for_testing [\"/path/to/model2.ifc\", \"/path/to/model3.ifc\"]\n    function_name \"get_elements_by_building_storey\"\n    function_description \"Get IFC elements grouped by their containing IfcBuildingStorey. Takes an IFC model path and element type, returns a dictionary mapping floor names to lists of elements.\"\n  }\n}\n",
    "generators.baml": "// This helps use auto generate libraries you can use in the language of\n// your choice. You can have multiple generators if you use multiple languages.\n// Just ensure that the output_dir is different for each generator.\ngenerator target {\n    // Valid values: \"python/pydantic\", \"typescript\", \"ruby/sorbet\", \"rest/openapi\"\n    output_type \"python/pydantic\"\n\n    // Where the generated code will be saved (relative to baml_src/)\n    output_dir \"../\"\n\n    // The version of the BAML package you have installed (e.g. same version as your baml-py or @boundaryml/baml).\n    // The BAML VSCode extension version should also match this version.\n    version \"0.211.2\"\n\n    // Valid values: \"sync\", \"async\"\n    // This controls what `b.FunctionName()` will be (sync or async).\n    default_client_mode sync\n}\n",
    "identify_helper_function.baml": "// HelperFunctionIdentifier - Analyzes successful Cobbie executions to identify reusable helper functions\n// This agent extracts generalizable patterns from successful question-answering sessions\n// to build a library of high-level BIM/IFC analysis tools\n\nfunction HelperFunctionIdentifier(\n  history: string @description(\"Complete execution history from Cobbie: thoughts, code, results, and final answer\"),\n  example_question: string @description(\"The question that was successfully answered by Cobbie\"),\n  existing_helper_functions: string @description(\"List of all existing helper functions with their docstrings and signatures\")\n) -> ToolIdentified {\n  client GLM_4_6\n  prompt #\"\n    You are an expert Python developer and software architect specializing in BIM (Building Information Modeling) systems.\n\n    Your task is to analyze a successful execution from COBBIE (a code-based BIM question-answering agent) and determine if a reusable helper function should be extracted.\n\n    EXECUTION CONTEXT:\n\n    Question Answered:\n    {{ example_question }}\n\n    Execution History (thoughts, code, and results):\n    {{ history }}\n\n    Existing Helper Functions:\n    {{ existing_helper_functions }}\n\n    YOUR ANALYSIS CRITERIA:\n\n    A helper function SHOULD be created if:\n    1. **Generalizability**: The code pattern can be applied to similar questions (not just this specific case)\n    2. **Abstraction Level**: It provides a higher-level abstraction than direct ifcopenshell calls\n    3. **Reusability**: Multiple future questions could benefit from this function\n    4. **Complexity Reduction**: It simplifies common BIM analysis tasks\n    5. **Distinctness**: It's significantly different from existing helper functions\n    6. **Clear Interface**: It can be defined with clear parameters and return types\n\n    A helper function SHOULD NOT be created if:\n    1. **Overfitting**: The code is too specific to this exact question or model\n    2. **Trivial**: It's just a simple wrapper around one ifcopenshell call\n    3. **Redundant**: An existing helper function already does this (or can easily be extended)\n    4. **Hard-coded values**: The code contains model-specific constants or assumptions\n    5. **One-off**: It's unlikely to be useful for other questions\n    6. **Too complex**: It combines unrelated operations that shouldn't be bundled together\n\n    ANALYSIS PROCESS:\n\n    1. Examine the execution history to identify:\n       - What ifcopenshell operations were used\n       - What patterns or logic were applied\n       - What intermediate results were computed\n       - What made this approach successful\n\n    2. Consider generalization:\n       - Can this pattern be abstracted to work with different IFC element types?\n       - Can it be parameterized to handle various filtering/sorting criteria?\n       - Does it represent a common BIM analysis operation?\n\n    3. Check against existing functions:\n       - Is there overlap with existing helper functions?\n       - Could an existing function be extended instead?\n\n    4. Define the helper function concept (if one should be created):\n       - Function name: Clear, descriptive, follows Python naming conventions\n       - Parameters: Generic, typed, well-defined\n       - Return type: Clear structure (list, dict, int, str, etc.)\n       - Purpose: Concise description of what it does and when to use it\n\n    IMPORTANT GUIDELINES:\n\n    - Prefer creating functions that encapsulate common BIM domain operations (e.g., \"get_elements_by_property\", \"calculate_total_area\")\n    - Avoid creating functions that are just thin wrappers (e.g., \"get_all_walls\" if it just calls model.by_type('IfcWall'))\n    - Focus on patterns that appeared necessary because ifcopenshell documentation queries were made\n    - Think about what would help COBBIE solve similar questions faster in the future\n\n    {{ ctx.output_format }}\n  \"#\n}\n\n// Test case for helper function identification with a clear reusable pattern\ntest HelperFunctionIdentifierPositiveTest {\n  functions [HelperFunctionIdentifier]\n  args {\n    example_question \"How many doors are on the ground floor?\"\n    history #\"\n      --- Iteration 1 ---\n      Thoughts: I need to first understand how to filter elements by floor/storey in IFC. Let me search the documentation.\n\n      Code:\n      result = query_ifcopenshell_docs(\"filter elements by storey level\")\n\n      Result:\n      IfcRelContainedInSpatialStructure relates elements to spatial structures like storeys...\n\n      --- Iteration 2 ---\n      Thoughts: Now I'll get all doors and filter by the ground floor storey\n\n      Code:\n      import ifcopenshell\n      model = ifcopenshell.open(path_ifc_model)\n\n      # Get ground floor storey\n      ground_floor = None\n      for storey in model.by_type('IfcBuildingStorey'):\n          if 'ground' in storey.Name.lower() or storey.Name == '0':\n              ground_floor = storey\n              break\n\n      # Get doors in ground floor\n      doors_on_ground = []\n      for rel in ground_floor.ContainsElements:\n          for element in rel.RelatedElements:\n              if element.is_a('IfcDoor'):\n                  doors_on_ground.append(element)\n\n      print(f\"Found {len(doors_on_ground)} doors on ground floor\")\n\n      Result:\n      Found 6 doors on ground floor\n\n      --- Final ---\n      Thoughts: Successfully identified all doors on the ground floor by traversing the spatial structure relationships.\n      Answer: There are 6 doors on the ground floor.\n    \"#\n    existing_helper_functions #\"\n      def query_ifcopenshell_docs(query: str) -> str:\n          '''Search ifcopenshell documentation for information'''\n\n      def web_search(query: str) -> str:\n          '''Search the web for general information'''\n    \"#\n  }\n}\n\n// Test case for a pattern that should NOT result in a helper function (too specific)\ntest HelperFunctionIdentifierNegativeTest {\n  functions [HelperFunctionIdentifier]\n  args {\n    example_question \"What is the height of wall with GlobalId '2O2Fr$t4X7Zf8NOew3FL9r'?\"\n    history #\"\n      --- Iteration 1 ---\n      Thoughts: I need to find the specific wall by GlobalId and get its height\n\n      Code:\n      import ifcopenshell\n      model = ifcopenshell.open(path_ifc_model)\n\n      wall = model.by_guid('2O2Fr$t4X7Zf8NOew3FL9r')\n      height = wall.Height\n\n      print(f\"Wall height: {height}\")\n\n      Result:\n      Wall height: 3.5\n\n      --- Final ---\n      Thoughts: Found the wall and extracted its height property directly.\n      Answer: The wall has a height of 3.5 meters.\n    \"#\n    existing_helper_functions #\"\n      def query_ifcopenshell_docs(query: str) -> str:\n          '''Search ifcopenshell documentation for information'''\n\n      def web_search(query: str) -> str:\n          '''Search the web for general information'''\n    \"#\n  }\n}\n\n// Test case with existing similar function (should not create duplicate)\ntest HelperFunctionIdentifierRedundantTest {\n  functions [HelperFunctionIdentifier]\n  args {\n    example_question \"How many windows are in the building?\"\n    history #\"\n      --- Iteration 1 ---\n      Thoughts: I'll count all windows in the model\n\n      Code:\n      import ifcopenshell\n      model = ifcopenshell.open(path_ifc_model)\n      windows = model.by_type('IfcWindow')\n      print(f\"Total windows: {len(windows)}\")\n\n      Result:\n      Total windows: 42\n\n      --- Final ---\n      Thoughts: Counted all window elements in the model.\n      Answer: There are 42 windows in the building.\n    \"#\n    existing_helper_functions #\"\n      def query_ifcopenshell_docs(query: str) -> str:\n          '''Search ifcopenshell documentation for information'''\n\n      def web_search(query: str) -> str:\n          '''Search the web for general information'''\n\n      def count_elements_by_type(ifc_file_path: str, ifc_type: str) -> int:\n          '''Count the number of elements of a specific IFC type in a model\n\n          Args:\n              ifc_file_path: Path to the IFC file\n              ifc_type: IFC element type (e.g., 'IfcWall', 'IfcWindow')\n\n          Returns:\n              int: Count of elements of the specified type\n          '''\n    \"#\n  }\n}\n",
    "schemas.baml": "// BAML schemas for BIM QA system\n\n// Code execution action (loop mode)\nclass CodeAction {\n  thoughts string @description(\"Reasoning for next step\")\n  python_code string @description(\"Code to execute\")\n}\n\n// Final answer action (completion mode)\nclass FinalAnswer {\n  thoughts string @description(\"Summary of findings\")\n  answer string @description(\"Final answer to user's question\")\n}\n\n// Tool creation result\nclass ToolCreationResult {\n  function_name string\n  function_implementation string\n  success bool\n}\n\n// Answer verification result\nclass SimilarityResult {\nsimilarity_score float\n  correct_answer bool\n  reasoning string\n}\n\n// Error analysis result\nclass ErrorAnalysisResult {\n  error_category string @description(\"faulty_tool, missing_tool, other\")\n  function_name string?\n  needs_new_tool bool\n}\n\n// Tool optimization result\nclass ToolOptimizationResult {\n  improvement string @description(\"create_new_tool, merge_existing_tools, update_existing_tool, no_action_needed\")\n  function_name string?\n  function_requirements string?\n  existing_tool_names string[]?\n}\n\n// Answer evaluation result\nclass AnswerEvaluationResult {\n  classification \"correct\" | \"wrong\" | \"abstained\" @description(#\"\n    Classification of the system response\n  \"#)\n\n  justification string @description(#\"\n    Brief explanation (2-3 sentences) of why this classification was chosen.\n  \"#)\n\n  confidence \"high\" | \"medium\" | \"low\" @description(#\"\n    Evaluator confidence level\n  \"#)\n}\n\n// Assessment result from ToolAssessor - tests function behavior without seeing implementation\nclass AssessmentResult {\n  assessment_status \"ok\" | \"needs_improvement\" @description(\"'ok' if function works as expected, 'needs_improvement' if issues found\")\n  assessment_details string @description(\"Detailed explanation of test results and any issues discovered\")\n  test_execution_log string? @description(\"Log of function execution and test cases attempted\")\n}\n\n// Extended result class for when tool creation is complete\nclass FunctionImplementation {\n  function_implementation string\n  confidence float?\n  needs_improvement bool\n}\n\n// Improved implementation from ToolCorrector - addresses assessment feedback\nclass ImprovedImplementation {\n  function_implementation string @description(\"Updated Python source code addressing assessment issues\")\n  reasoning string @description(\"Explanation of changes made and how they address the feedback\")\n  changes_summary string? @description(\"Brief summary of the main changes made\")\n}\n\n// Cleaned code from CodeCleaner - fixes syntax and compilation errors\nclass CleanedCode {\n  function_implementation string @description(\"Python code with syntax errors fixed\")\n  reasoning string @description(\"Explanation of syntax fixes and corrections applied\")\n  success bool @description(\"Whether the cleaning was successful\")\n}\n\n// Aligned question-answer pair for dataset cleaning\nclass AlignedQAPair {\n  thought string @description(\"Analysis of the alignment between question and answer, and reasoning for any changes\")\n  aligned_question string @description(\"Question reformulated to align with answer structure and scope (or original if already aligned)\")\n  aligned_answer string @description(\"Answer with improved formatting/clarity while preserving factual content (or original if already good)\")\n  was_modified bool @description(\"Whether any modifications were made to question or answer\")\n}\n\n// Successful outcome - function has been tested and improved successfully\nclass TestAndImproveSuccess {\n  function_implementation string @description(\"Final validated function implementation\")\n  assessment_details string @description(\"Final assessment confirming function works correctly\")\n  iterations_used int @description(\"Number of iterations needed to achieve success\")\n  total_time_seconds float @description(\"Total time taken for testing and improvement\")\n}\n\n// Error outcome - testing and improvement process failed\nclass TestAndImproveError {\n  error_message string @description(\"Detailed error description\")\n  iterations_completed int @description(\"Number of iterations completed before failure\")\n  final_assessment_status string? @description(\"Last known assessment status, if any\")\n  partial_function_implementation string? @description(\"Best function implementation achieved, if any\")\n}\n\n// Category validation result for question-answer pairs\nclass CategoryValidationResult {\n  validated_category string @description(\"The correct category (1, 2, 3, or 4) according to the taxonomy\")\n  updated bool @description(\"Whether the category was changed from the original\")\n  thought string @description(\"Reasoning for the category classification and any changes made\")\n}\n\n// Helper function identification result from successful Cobbie executions\nclass ToolIdentified {\n  thoughts string @description(\"Step-by-step analysis of the execution history to identify reusable patterns\")\n  new_tool bool @description(\"Whether a new helper function should be created (true) or not (false)\")\n  new_tool_name string @description(\"Suggested name for the new helper function (empty string if new_tool is false)\")\n  new_tool_description string @description(\"Detailed description of what the helper function should do, its parameters, return type, and use cases (empty string if new_tool is false)\")\n}\n\n// Helper function implementation result - final output from HelperFunctionCreator\nclass NewHelperFunction {\n  thoughts string @description(\"Summary of development process, testing performed, and validation results\")\n  function_implementation string @description(\"Complete Python function implementation including imports, docstring, and type hints\")\n  success bool @description(\"Whether the function is complete, tested, and ready for use\")\n}\n",
    "test_and_improve.baml": "// ToolAssessor function - tests function behavior using CodeAct pattern\n// Returns either CodeAction (continue testing) or AssessmentResult (final assessment)\nfunction ToolAssessor(\n  function_name: string,\n  function_requirements: string,\n  path_ifc_model: string,\n  available_tools: string,\n  previous_attempts: string? @description(\"Previous test execution results, if any\")\n) -> CodeAction | AssessmentResult {\n  client GLM_4_6\n  prompt #\"\n    You are testing a Python function that has been created to meet specific requirements.\n    Your role is to thoroughly test the function as a BLACK BOX - you can use the function but cannot see its implementation.\n\n    FUNCTION TO TEST:\n    {{ function_name }}\n\n    REQUIREMENTS TO VERIFY:\n    {{ function_requirements }}\n\n    TEST MODEL PATH:\n    {{ path_ifc_model }}\n\n    AVAILABLE TOOLS:\n    {{ available_tools }}\n\n    {% if previous_attempts %}\n    PREVIOUS TEST RESULTS:\n    {{ previous_attempts }}\n    {% endif %}\n\n    CRITICAL INSTRUCTIONS:\n    You must return EITHER a CodeAction object OR an AssessmentResult object - NOT explanations.\n\n    If you need to run more test code, return CodeAction with:\n    - python_code: The exact Python code to execute\n    - thoughts: Brief explanation of what you're testing\n\n    If you have enough information for final assessment, return AssessmentResult with:\n    - assessment_status: \"ok\" or \"needs_improvement\"\n    - assessment_details: Detailed explanation of test results\n    - test_execution_log: Optional log of tests performed\n\n    TESTING APPROACH:\n    1. Test normal operation with the provided IFC model\n    2. Test edge cases (invalid paths, wrong file types, etc.)\n    3. Verify return types and error handling\n    4. Check robustness and performance\n\n    {{ ctx.output_format }}\n  \"#\n}\n\n// ToolCorrector function - improves implementation based on detailed assessment feedback\n// Uses CodeAct pattern to test improvements and iterate\n// Returns either CodeAction (continue improving) or ImprovedImplementation (final result)\nfunction ToolCorrector(\n  function_requirements: string,\n  function_name: string,\n  current_function_implementation: string,\n  detailed_assessment: string,\n  path_ifc_model: string,\n  available_tools: string,\n  previous_attempts: string? @description(\"Previous improvement attempts, if any\")\n) -> CodeAction | ImprovedImplementation {\n  client GLM_4_6\n  prompt #\"\n    You are improving a Python function based on detailed assessment feedback.\n\n    FUNCTION NAME:\n    {{ function_name }}\n\n    REQUIREMENTS:\n    {{ function_requirements }}\n\n    CURRENT IMPLEMENTATION:\n    {{ current_function_implementation }}\n\n    ASSESSMENT FEEDBACK TO ADDRESS:\n    {{ detailed_assessment }}\n\n    TEST MODEL PATH:\n    {{ path_ifc_model }}\n\n    AVAILABLE TOOLS:\n    {{ available_tools }}\n\n    {% if previous_attempts %}\n    PREVIOUS IMPROVEMENT ATTEMPTS:\n    {{ previous_attempts }}\n    {% endif %}\n\n    CRITICAL INSTRUCTIONS:\n    You must return EITHER a CodeAction object OR an ImprovedImplementation object - NOT explanations.\n\n    If you need to test code or continue improving, return CodeAction with:\n    - python_code: The exact Python code to execute\n    - thoughts: Brief explanation of what you're testing or improving\n\n    If the function is fully improved and ready, return ImprovedImplementation with:\n    - function_implementation: The complete improved Python code\n    - reasoning: Explanation of changes made\n    - changes_summary: Optional brief summary of main changes\n\n    IMPROVEMENT REQUIREMENTS:\n    1. Fix every issue mentioned in the assessment feedback\n    2. Ensure proper return types (int, str, list, dict as specified)\n    3. Include comprehensive docstrings and type hints\n    4. Add error handling with meaningful error messages\n    5. Follow Python best practices for readability\n\n    {{ ctx.output_format }}\n  \"#\n}\n\n// CodeCleaner function - fixes syntax errors and compilation issues\n// Replaces DSPy ChainOfThought with direct BAML implementation\nfunction CodeCleaner(\n  faulty_code: string,\n  error_message: string\n) -> CleanedCode {\n  client GLM_4_6\n  prompt #\"\n    Fix syntax and compilation errors in Python function source code.\n\n    FAULTY CODE:\n    {{ faulty_code }}\n\n    ERROR MESSAGE:\n    {{ error_message }}\n\n    Your task is to fix the syntax errors and return a CleanedCode object with:\n    - function_implementation: The corrected Python code\n    - reasoning: Brief explanation of fixes made\n    - success: boolean indicating if cleaning was successful\n\n    Fix only syntax errors, import issues, and compilation problems.\n    Do not change the fundamental logic or add new functionality.\n    Ensure the code can execute without syntax errors.\n\n    {{ ctx.output_format }}\n  \"#\n}\n\n// Test functions for validation\n\ntest ToolAssessorTest {\n  functions [ToolAssessor]\n  args {\n    function_name \"count_doors\"\n    function_requirements \"Count all doors in an IFC model. Return an integer count.\"\n    path_ifc_model \"/Users/sylvainhellin/GitHub/4_phd/cobbie/src/experiment/bim_models/duplex/arc.ifc\"\n    available_tools #\"\n      def count_doors(ifc_file_path: str) -> int:\n          '''Count all doors in an IFC model'''\n\n      def web_search(query: str) -> str:\n          '''Search the web for information'''\n    \"#\n  }\n}\n\ntest ToolCorrectorTest {\n  functions [ToolCorrector]\n  args {\n    function_name \"count_doors\"\n    function_requirements \"Count all doors in an IFC model. Return an integer count.\"\n    current_function_implementation #\"\n      def count_doors(ifc_file_path: str) -> int:\n          \"\"\"Count all doors in an IFC model.\"\"\"\n          model = ifcopenshell.open(ifc_file_path)\n          doors = model.by_type(\"IfcDoor\")\n          return str(len(doors))  # Wrong return type\n    \"#\n    detailed_assessment \"The function correctly counts doors (14) but returns a string instead of an integer, violating requirement #4. The function signature indicates it should return an integer.\"\n    path_ifc_model \"/Users/sylvainhellin/GitHub/4_phd/cobbie/src/experiment/bim_models/duplex/arc.ifc\"\n    available_tools #\"\n      def web_search(query: str) -> str:\n          '''Search the web for information'''\n    \"#\n  }\n}\n\ntest CodeCleanerTest {\n  functions [CodeCleaner]\n  args {\n    faulty_code #\"\n      def count_doors(ifc_file_path: str) -> int:\n          \"\"\"Count all doors in an IFC model.\"\"\"\n          model = ifcopenshell.open(ifc_file_path)  # Missing import\n          doors = model.by_type(\"IfcDoor\"  # Missing closing parenthesis\n          return str(len(doors))\n    \"#\n    error_message \"'(' was never closed (<string>, line 4)\"\n  }\n}\n",
    "tool_creator.baml": "// Main ToolCreator function returning either continue action or final implementation\nfunction ToolCreator(\n  function_requirements: string,\n  function_name: string,\n  function_boilerplate: string,\n  path_ifc_model: string,\n  available_tools: string?,\n  previous_attempts: string?\n) -> CodeAction | FunctionImplementation {\n  client GLM_4_6\n  prompt #\"\n    You are an expert Python programmer specializing in creating tools for BIM (Building Information Modeling) analysis using the IfcOpenShell library.\n\n    Your task is to create a new Python function based on the given requirements. The function must:\n\n    1. Return proper data structures (e.g., lists and dictionaries), not formatted strings\n    2. Be well-documented with docstrings and type hints\n    3. Be explicit regarding assumptions (e.g., if using Revit-specific property sets)\n    4. Follow proper Python error handling patterns\n\n    {% if path_ifc_model %}\n    IMPORTANT: The IFC model path for testing is: {{ path_ifc_model }}\n    Use this exact path in your Python code when testing with IFC files.\n    {% endif %}\n\n    FUNCTION REQUIREMENTS:\n    {{ function_requirements }}\n\n    FUNCTION NAME: {{ function_name }}\n\n    {% if function_boilerplate %}\n    REQUIRED BOILERPLATE (must include at beginning):\n    {{ function_boilerplate }}\n    {% endif %}\n\n    {% if available_tools %}\n    AVAILABLE TOOLS:\n    {{ available_tools }}\n    {% endif %}\n\n    {% if previous_attempts %}\n    PREVIOUS ATTEMPTS:\n    {{ previous_attempts }}\n    {% endif %}\n\n    You can either:\n    1. Write Python code to create/test the function (returns CodeAction)\n    2. Provide the final function implementation if complete (returns FunctionImplementation)\n\n    Choose your next action:\n    - CodeAction: If you need to write/execute Python code to develop the function\n    - FunctionImplementation: If you have a complete, working function ready\n\n    {{ ctx.output_format }}\n  \"#\n}\n\n// Fallback function to extract function implementation from conversation history\nfunction CodeExtractor(\n  function_name: string,\n  conversation_history: string\n) -> FunctionImplementation {\n  client GLM_4_6\n  prompt #\"\n    Extract the Python function implementation from the conversation history.\n\n    Function name to extract: {{ function_name }}\n\n    Conversation history:\n    {{ conversation_history }}\n\n    Find and return the complete Python function implementation including any imports, docstrings, and helper functions.\n\n    {{ ctx.output_format }}\n  \"#\n}\n\n// Test function for ToolCreator\ntest ToolCreatorTest {\n  functions [ToolCreator]\n  args {\n    function_requirements \"Create a function that counts all walls in an IFC model. The function should take an IFC file path as input and return the total count as an integer.\"\n    function_name \"count_walls\"\n    function_boilerplate \"import ifcopenshell\\nimport typing\\n\"\n    path_ifc_model \"/path/to/test/model.ifc\"\n    available_tools #\"\n      def get_ifc_model_info(ifc_file_path: str) -> dict:\n          '''Get basic information about an IFC model'''\n\n      def web_search(query: str) -> str:\n          '''Search the web for information'''\n    \"#\n  }\n}\n\ntest CodeExtractorTest {\n  functions [CodeExtractor]\n  args {\n    function_name \"count_walls\"\n    conversation_history #\"\n      User: Create a function to count walls\n      Assistant: Here's the implementation:\n\n      ```python\n      import ifcopenshell\n      from typing import List\n\n      def count_walls(ifc_file_path: str) -> int:\n          \\\"\\\"\\\"Count all wall elements in an IFC model.\n\n          Args:\n              ifc_file_path: Path to the IFC file\n\n          Returns:\n              Total number of wall elements\n          \\\"\\\"\\\"\n          model = ifcopenshell.open(ifc_file_path)\n          walls = model.by_type('IfcWall')\n          return len(walls)\n      ```\n\n      This function opens the IFC file and counts all IfcWall elements.\n    \"#\n  }\n}",
}

def get_baml_files():
    return _file_map